#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Purpose: rotate the fnox age key when the private key is lost. The existing
# ciphertexts in fnox.toml are unrecoverable without the old key, so this
# generates a new identity, points fnox at it, re-enters every shared secret
# (re-encrypting under the new key), updates the FNOX_AGE_KEY GitHub secret,
# and opens a pull request with the store (`master` refuses direct pushes,
# ADR-0054).
#
# Run from anywhere:  ./scripts/rotate-fnox-age-key.sh
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

cd "$(git rev-parse --show-toplevel)"

AGE_KEY_FILE="${FNOX_AGE_KEY_FILE:-$HOME/.config/fnox/age.txt}"

# set_fnox NAME VALUE encrypts VALUE into fnox.toml under the current
# recipient. Value via stdin so it never lands in argv, history, or `ps`.
set_fnox() {
  local name="$1" value="$2" err
  if [[ -z "$value" ]]; then warn "skipping $name (empty)"; return 0; fi
  if err=$(printf '%s' "$value" | fnox set "$name" 2>&1 >/dev/null); then
    say "re-encrypted: $name"
  else
    warn "failed to set $name"
    note "$err"
    SKIPPED+=("fnox set $name")
  fi
}

banner "VMB: rotate the fnox age key"

# ── Stage 1: new age identity ─────────────────────────────────────────────
stage "Generate a new age identity"
warn "The old private key is lost, so nothing currently in fnox.toml can be"
warn "decrypted again. This wizard re-enters every secret under a new key."
if ! command -v age-keygen >/dev/null 2>&1; then
  warn "age-keygen not found — run 'mise install' first (age is pinned in .mise.toml)."
  exit 1
fi
mkdir -p "$(dirname "$AGE_KEY_FILE")"
chmod 700 "$(dirname "$AGE_KEY_FILE")"
if [[ -f "$AGE_KEY_FILE" ]]; then
  backup="${AGE_KEY_FILE}.bak.$(date +%Y%m%d%H%M%S)"
  mv "$AGE_KEY_FILE" "$backup"
  note "existing key backed up to $backup"
fi
age-keygen -o "$AGE_KEY_FILE" >/dev/null
chmod 600 "$AGE_KEY_FILE"
PUBLIC_KEY=$(age-keygen -y "$AGE_KEY_FILE")
say "new recipient (public key): $PUBLIC_KEY"

# ── Stage 2: point fnox.toml at the new recipient ─────────────────────────
stage "Point fnox.toml at the new recipient"
if grep -qE 'recipients = \["age1[^"]*"\]' fnox.toml; then
  sed -E "s|recipients = \[\"age1[^\"]*\"\]|recipients = [\"$PUBLIC_KEY\"]|" fnox.toml > fnox.toml.tmp
  mv fnox.toml.tmp fnox.toml
  say "updated fnox.toml recipients"
else
  warn "couldn't find a single recipients line — update fnox.toml by hand before continuing."
  SKIPPED+=("Update fnox.toml recipients")
fi

# ── Stage 3: re-enter every secret ────────────────────────────────────────
stage "Re-enter the shared secrets"
say "Each value is re-encrypted into fnox.toml under the new key."
note "DATABASE_URL is not one of them any more: the local development branch's"
note "connection string is per-developer and lives in the gitignored"
note "fnox.local.toml overlay (ADR-0029). This rotation does not need it."

generated_secret=$(openssl rand -base64 32)
say "A fresh BETTER_AUTH_SECRET will be used unless you paste your own."
ask_secret BETTER_AUTH_SECRET "BETTER_AUTH_SECRET (Enter to use the generated one):"
BETTER_AUTH_SECRET="${BETTER_AUTH_SECRET:-$generated_secret}"

# fnox is the local-dev / CI store (ADR-0011), so BETTER_AUTH_URL and WEB_URL
# re-enter the *local* `wrangler dev` origins here — not the production ones.
# Production origins live in the Worker secrets and the Pages API_URL binding
# (ARCHITECTURE.md §9), never in fnox. Default to the local origins so a
# rotation on a fresh checkout does not leave them empty.
DEV_API_URL="${DEV_API_URL:-http://localhost:8787}"
DEV_WEB_URL="${DEV_WEB_URL:-http://localhost:5173}"
write_env BETTER_AUTH_URL "${BETTER_AUTH_URL:-$DEV_API_URL}"
write_env WEB_URL "${WEB_URL:-$DEV_WEB_URL}"
ask BETTER_AUTH_URL "BETTER_AUTH_URL (local dev):"
ask WEB_URL "WEB_URL (local dev):"

open_url "https://resend.com/api-keys"
step "Create (or copy) a Sending-access Resend API key."
ask_secret RESEND_API_KEY "RESEND_API_KEY:"
ask EMAIL_FROM "EMAIL_FROM:"

set_fnox BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"
set_fnox BETTER_AUTH_URL "$BETTER_AUTH_URL"
set_fnox WEB_URL "$WEB_URL"
set_fnox RESEND_API_KEY "${RESEND_API_KEY:-}"
set_fnox EMAIL_FROM "${EMAIL_FROM:-}"

# ── Stage 4: publish the key to GitHub Actions ────────────────────────────
stage "Publish the new key to GitHub Actions"
step "CI needs FNOX_AGE_KEY set to the bare AGE-SECRET-KEY-1… line — not the whole file."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if grep "AGE-SECRET-KEY" "$AGE_KEY_FILE" | gh secret set FNOX_AGE_KEY; then
    say "updated repo secret FNOX_AGE_KEY"
  else
    warn "failed to set FNOX_AGE_KEY"
    SKIPPED+=("gh secret set FNOX_AGE_KEY")
  fi
else
  warn "gh not ready — set FNOX_AGE_KEY manually to the AGE-SECRET-KEY-1… line."
  SKIPPED+=("gh secret set FNOX_AGE_KEY")
fi

if value=$(fnox get BETTER_AUTH_SECRET 2>/dev/null) && [[ -n "$value" ]]; then
  say "verified: fnox can decrypt the new store locally"
else
  warn "fnox get BETTER_AUTH_SECRET failed — the store is not decryptable with the new key."
  SKIPPED+=("Verify local decryption")
fi
warn "Back up $AGE_KEY_FILE in a password manager NOW — losing it again means another rotation."

# ── Stage 5: open a pull request with the re-encrypted store ──────────────
# `master` is protected (ADR-0054): a push to it is refused, so the store goes
# in on a branch of its own and a pull request, whatever branch this ran on.
stage "Open a pull request with the re-encrypted store"
say "fnox.toml now holds ciphertext encrypted to the new key."
ROTATE_BRANCH="chore/secrets/rotate-fnox-age-key-$(date +%Y%m%d-%H%M%S)"
base=$(gh repo view --json defaultBranchRef --jq .defaultBranchRef.name 2>/dev/null || echo master)
ahead=$(git rev-list --count "origin/$base..HEAD" 2>/dev/null || echo 0)
if [[ "$ahead" != 0 ]]; then
  warn "HEAD is $ahead commit(s) ahead of origin/$base: the pull request would carry them."
  note "Run this from a checkout of $base to keep the pull request to fnox.toml."
fi
if confirm "Commit fnox.toml on $ROTATE_BRANCH, push it and open a pull request?"; then
  if ! git switch -c "$ROTATE_BRANCH" >/dev/null 2>&1; then
    warn "couldn't create branch $ROTATE_BRANCH (does it exist?). Nothing committed."
    SKIPPED+=("Commit fnox.toml on a new branch, push it and open a pull request")
  elif git add fnox.toml && git commit -m "chore(secrets): rotate fnox age key" >/dev/null 2>&1; then
    say "committed fnox.toml on $ROTATE_BRANCH"
    if git push -u origin HEAD \
      && gh pr create --base "$base" --head "$ROTATE_BRANCH" \
        --title "chore(secrets): rotate fnox age key" \
        --body "$(printf '%s\n' \
          '## Summary' '' \
          'Re-encrypts the shared secrets in fnox.toml under a new age key. FNOX_AGE_KEY was updated to match.' '' \
          '## Merge Danger' '' \
          '**Door:** one-way')"; then
      say "opened a pull request: merge it once CI is green"
    else
      warn "push or pull request failed: push $ROTATE_BRANCH and open the PR by hand so CI sees the new ciphertext"
      SKIPPED+=("Push $ROTATE_BRANCH and open a pull request")
    fi
  else
    warn "git commit failed (already committed? hooks?)"
    SKIPPED+=("Commit fnox.toml")
  fi
else
  SKIPPED+=("Commit fnox.toml on a branch and open a pull request")
fi

# ──────────────────────────────────────────────────────────────────────────

finish
